import hashlib, json, os, sys
out = sys.argv[1]
pkg = ".dev/tasks/to-do/TASK-WF-issueSummary-20261125-164859"
files = []
for root, _, names in os.walk(pkg):
    for n in names:
        files.append(os.path.join(root, n))
files.append("src/superclaude/hooks/scripts/launch-level-guard.sh")
def sha(p): return hashlib.sha256(open(p, "rb").read()).hexdigest()
lst = sorted((p, sha(p)) for p in files)
tree = hashlib.sha256(json.dumps(lst).encode()).hexdigest()
with open(os.path.join(out, "artifacts", "input-snapshot.yaml"), "w") as f:
    f.write(f"input_tree_sha256: {tree}\nfile_list:\n")
    for p, h in lst:
        f.write(f"  - path: {p}\n    sha256: {h}\n")
    f.write(f"file_count: {len(lst)}\n")
print(tree, len(lst))
for p, h in lst: print(h[:12], p)
